// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {airPort} from "../src/airPort.sol";

contract InvMutTest is Test {
    airPort c;
    function setUp() public { c = new airPort(); }

    // fuzz parameters: an arbitrary "from" address and an array of recipient addresses and a value
    function testFuzz_property(address from, address[] memory tos, uint256 v) public {
        // admissible domain: tos must be non-empty because the function requires that
        vm.assume(tos.length > 0);

        // Deploy a recording helper that exposes the exact signature transferFrom(address,address,uint256)
        // so that calls from c using abi.encodeWithSelector reach the typed function and record arguments.
        Recorder rec = new Recorder();

        // Call through c.transfer and observe whether it returns (does not revert)
        bool ok;
        try c.transfer(from, address(rec), tos, v) {
            ok = true;
        } catch {
            ok = false;
        }

        // The invariant: for a correct C, if the call completed (ok == true), Recorder.recordsCount() equals tos.length
        // because C should call the callee once for each element of tos. The mutant that loops to length-1 will
        // result in recordsCount() == tos.length - 1 for some inputs where all external calls succeed.
        // We assert that when c.transfer returned successfully, the recorder observed exactly tos.length calls.
        assertTrue(!ok || rec.recordsCount() == tos.length);
    }
}

contract Recorder {
    // store decoded calls
    struct Call { address from; address to; uint256 v; }
    Call[] public calls;

    // exact signature that C dispatches to: transferFrom(address,address,uint256)
    function transferFrom(address from_, address to_, uint256 v_) external returns (bool) {
        // record the call
        calls.push(Call({from: from_, to: to_, v: v_}));
        return true;
    }

    // helper getter for the test to read how many calls were recorded
    function recordsCount() external view returns (uint256) { return calls.length; }
}
